      "s.feeds.limitReached": "La liste des flux est pleine (maximum {max} flux)",
      "s.antigravity.title": "Sessions Antigravity",
      "s.antigravity.hint": "Affiche les conversations Antigravity récentes dans le widget Sessions IA (désactivé par défaut). Seules les métadonnées des étapes et les compteurs de jetons sont conservés ; les prompts, les réponses et les arguments des outils ne sont jamais affichés, stockés ni envoyés.",
