      "s.antigravity.shareSessionTitles": "Afficher les titres des conversations Antigravity sur le téléphone (Antigravity les tire de la conversation)",
      "s.oled.lead": "Pour les écrans OLED qui affichent la même page pendant des heures, le thème noir AMOLED et l'écran de nuit aident également.",
      "s.oled.idleDimHint": "Un toucher l’éclaire à nouveau sans appuyer sur quoi que ce soit, tout comme un changement de page, une notification et une invite d’autorisation.",
      "s.display.orientationHint": "Vous concevez les pages en mode paysage. En mode portrait, le panneau organise les widgets de haut en bas. Les tablettes utilisent les mêmes pages, mais plus grandes.",
      "s.pageSwitch.lead": "Au lieu de sauter, le téléphone affiche « Claude a besoin de moi — basculement vers l’IA dans 3 … » avec Stay et Go maintenant, puis disparaît. Il ne retire jamais une page lorsque vous utilisez le panneau, et les règles qui se déclenchent les unes après les autres attendent leur tour au lieu de faire rebondir l’écran d’avant en arrière.",
