      "s.kiosk.homeScreen": "Utilisez le panneau comme écran d'accueil du téléphone: il démarre après un redémarrage et Home retourne à elle (désactivez pour obtenir votre lanceur de retour)",
      "s.kiosk.keepAwake": "Gardez le téléphone éveillé: désactivez l'économiseur d'écran Android (il commence sur le chargeur) et gardez l'écran allumé lorsque branché (réglé sur USB)",
      "s.kiosk.openOnConnect": "Ouvrir PhoneBox lorsque le téléphone est branché: réveiller le téléphone et amener le panneau à l'avant chaque fois qu'il se connecte sur USB (désactivez-le pour l'ouvrir vous-même, pour un téléphone que vous utilisez également pour tester les applications)",
      "s.kiosk.followLock": "Suivez le verrouillage de l'ordinateur: éteignez l'écran du téléphone lorsque macOS se verrouille; réveillez-le et ouvrez PhoneBox lorsque macOS se déverrouille (ADB requis; déverrouiller les téléphones sécurisés par un code PIN ou mot de passe manuellement)",
      "s.claude.shareConversation": "Afficher la conversation sur le téléphone (appuyez sur une session Claude Code pour voir ses messages et étapes récents; ce sont vos invites et les réponses de Claude, envoyées uniquement à votre téléphone)",
      "s.claude.onlyWhenAway": "Seulement quand je suis loin du PC (pas de clavier ou de souris pendant une minute)",
      "s.claude.shareSessionTitles": "Afficher les titres de chat Claude Code sur le téléphone (Claude Code souvent les tire de votre première invite)",
