      "s.antigravity.title": "Sessioni di Antigravity",
      "s.antigravity.hint": "Mostra le chat recenti di Antigravity nel widget Sessioni IA (disattivato per impostazione predefinita). Vengono conservati solo i metadati dei passaggi e i contatori dei token; prompt, risposte e argomenti degli strumenti non vengono mai mostrati, salvati o inviati.",
