      "s.oled.lead": "Per gli schermi OLED che mostrano la stessa pagina per ore, il tema nero AMOLED e lo schermo notturno aiutano anche.",
      "s.oled.idleDimHint": "Un tocco lo illumina di nuovo senza premere nulla; così fanno un cambio pagina, una notifica e un prompt per l'autorizzazione.",
      "s.display.orientationHint": "Si progettano le pagine in orizzontale; in verticale il pannello dispone i widget da solo, dall'alto verso il basso.I tablet utilizzano le stesse pagine, solo più grandi.",
      "s.pageSwitch.lead": "Come regole, webhooks e il ritorno inattivo cambiano la pagina. Invece di saltare, il telefono mostra “Claude ha bisogno di me — passando all’AI tra 3…” con Stay and Go now, poi si dissolve. Non tira mai via una pagina mentre stai usando il pannello, e le regole che si attivano una dopo l’altra aspettano il loro turno invece di rimbalzare sullo schermo avanti e indietro.",
