      "s.claude.hint": "Kiedy Claude Code prosi o pozwolenie (na uruchomienie polecenia, edycję pliku…) telefon wyświetla żądanie z <b> Allow </b> i <b> Deny </b> . Jeśli telefon nie jest podłączony lub nikt nie odpowiada na czas, Claude Code zapyta w terminalu jak zwykle, potrzebuje małego haka w <code>~/.claude/settings.json</code>; PhoneBox dodaje go dla Ciebie (kopia zapasowa jest przechowywana obok pliku).",
      "s.wifi.lead": "Sparuj telefon, podłączając go raz za razem USB Po włączeniu tego (i ponownym uruchomieniu) lub bez kabla: <b>Połącz telefon z komputerem Wi-Fi</b> Pokazuje a QR Telefon wtedy komunikuje się z tym komputerem za pomocą protokołu HTTPS, ufa tylko certyfikatowi tego komputera i musi przedstawić tajny klucz. Telefon i ten komputer muszą być podłączone do tej samej sieci lub oba muszą być podpięte do jednego portu USB. <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, który działa również z innego miejsca lub przez oddzielne Wi-Fi Sieci. Windows Zapora pyta raz &mdash; pozwól na to (zaznacz typ sieci Tailscale Używa się też).",
