      "s.kiosk.homeScreen": "Используйте панель как основной экран телефона: он начинается после перезагрузки и Home возвращается к нему (выключите, чтобы вернуть ваш стартер)",
      "s.kiosk.keepAwake": "Держите телефон в сознании: выключите заставку экрана Android (она начинается на зарядном устройстве) и держите экран включенным, пока подключен к сети (установить над USB)",
