      "s.kiosk.followLock": "Следуйте за блокировкой компьютера: выключите экран телефона, когда macOS заблокирован; пробудить его и открыть PhoneBox, когда macOS разблокирует (требуется ADB; разблокировать телефоны, защищенные PIN-кодом или паролем вручную)",
